def generate_inputs(device):
    x = torch.zeros(128, 512, device=device, dtype=torch.float32)
    A = 5000.0
    for tile_idx in range(16):
        start_col = tile_idx * 32
        for j in range(32):
            col = start_col + j
            if tile_idx % 2 == 0:
                # Even tiles: alternating pattern
                x[:, col] = A if j % 2 == 0 else -A
            else:
                # Odd tiles: all same sign but row-dependent
                for row in range(128):
                    row_sign = 1.0 if (row // 32) % 2 == 0 else -1.0
                    x[row, col] = A * row_sign * (1.0 + 0.01 * j)
    return [x]
